import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/xfr5')
from lib import *
o=[]
o.append(R(2784,"Poitrine de dinde glacée à la moutarde de Dijon et à l'ananas",
"Quand vous cherchez de bonnes sources de protéines, pensez à la dinde. C'est un excellent changement par rapport au poulet et au bœuf, et Maria, diététicienne rénale DaVita en Caroline du Nord, propose une savoureuse recette de poitrine de dinde glacée à la moutarde de Dijon et à l'ananas, adaptée aux reins.",
"20","3 onces",
["1 poitrine de dinde de 5 livres","1/3 tasse de garniture à l'ananas","2 cuillères à café de moutarde de type Dijon","1 cuillère à café de jus de citron"],
["Lavez la poitrine de dinde et préparez-la pour le rôtissage.","Placez-la dans un plat à rôtir, côté poitrine vers le haut ; couvrez et faites cuire à 350° F pendant 1-1/2 heure (température interne de 170° à l'aide d'un thermomètre à viande).","Dans un petit bol, mélangez les ingrédients restants et remuez pour bien les combiner.","Sortez la poitrine de dinde du four et badigeonnez-la de glaçage.","Remettez la dinde au four et faites cuire à découvert pendant 30 minutes.","Sortez du four. Laissez reposer la dinde 15 minutes avant de la trancher."],
["Le surplus de glaçage peut être servi à part comme sauce d'accompagnement.","Ce glaçage peut aussi être utilisé sur du poulet.","Maladie rénale chronique sans dialyse : cette recette plus riche en protéines peut convenir à votre alimentation si la taille de la portion est ajustée pour réduire l'apport en protéines. Les ajustements doivent être basés sur votre prescription individuelle en protéines. En cas de doute, consultez votre diététicien."],
["3 viande"]))
o.append(R(2790,"Sauce au jus de poitrine de bœuf",
"Passez la sauce pour ajouter de la saveur à vos plats de bœuf. La sauce au jus de poitrine de bœuf est une recette adaptée aux reins, facile à préparer avec le jus de cuisson de la poitrine ou un bouillon de bœuf pauvre en sodium et quelques autres assaisonnements. Pour des plats de bœuf moelleux et délicieux, pensez à préparer cette sauce.",
"8","1/4 tasse",
["jus de cuisson d'une poitrine de bœuf cuite","2 cuillères à soupe de farine blanche tout usage","1 cuillère à soupe de vinaigre balsamique","1 cuillère à café de sauce Worcestershire"],
["Filtrez le jus de cuisson de la poitrine et versez-le dans une grande tasse à mesurer. Ajoutez de l'eau pour obtenir 2 tasses de bouillon.","Dans un petit plat, mélangez 1/2 tasse de bouillon de jus de cuisson et la farine. Fouettez jusqu'à consistance lisse. Ajoutez le reste du bouillon, le vinaigre et la sauce Worcestershire.","Dans une casserole moyenne, chauffez le bouillon en remuant à feu moyen à moyen-doux jusqu'à ce qu'il épaississe et atteigne un bouillonnement.","Retirez du feu. Servez sur la viande cuite."],
["Remplacez par 2 tasses de bouillon pauvre en sodium si vous n'avez pas de jus de cuisson.","Un sandwich chaud au rôti de bœuf avec la sauce au jus de poitrine de bœuf fait un délicieux déjeuner.","Pour une sauce lisse et sans grumeaux, délayez la farine dans une petite quantité de bouillon avant de la mettre sur le feu.","Évitez de chauffer la sauce trop rapidement. Utilisez un feu moyen-doux à moyen et remuez constamment dès que le mélange commence à épaissir."],
["1/2 sel"]))
o.append(R(2791,"Œufs du petit-déjeuner de la Saint-Valentin",
"Vous serez sous le charme de cette recette DaVita adaptée aux reins, les œufs du petit-déjeuner de la Saint-Valentin.",
"2","3/4 tasse",
["1 tortilla de maïs de 6 po","2 blancs d'œufs","2 œufs","3 oignons verts, hachés","2 tranches de tomate, chacune de 1/4 po d'épaisseur, hachées","2 cuillères à soupe d'huile de canola"],
["Placez la tortilla de maïs au micro-ondes pendant 1-1/2 à 2 minutes.","Émiettez la tortilla en morceaux de la taille de chips.","Mélangez les œufs et les blancs d'œufs ; faites-les brouiller de façon moelleuse et réservez.","Mettez l'huile dans une poêle à feu moyen et, lorsqu'elle est chaude, ajoutez les oignons et faites sauter 1 minute.","Ajoutez la tortilla, la tomate et les œufs.","Remuez jusqu'à ce que les œufs soient cuits. Servez chaud et bon appétit."],
["Chaque micro-ondes a des temps de cuisson différents, mais vous saurez que la tortilla de maïs est prête lorsqu'elle dégage une odeur de pop-corn en train d'éclater.","Utilisez 6 chips de tortilla de maïs non salées pour gagner du temps.","Les tortillas de maïs sont riches en phosphore comparées aux tortillas de blé ou au pain blanc. Limitez les tortillas de maïs pour aider à réduire le phosphore, surtout si vos résultats de laboratoire ont été supérieurs à la normale."],
["1-1/2 viande","1/2 légume, teneur moyenne en potassium","1/2 féculent","2 matière grasse"]))
o.append(R(2795,"Biscuits dorés à la semoule de maïs",
"Convenant aux régimes pour le diabète, la dialyse et la maladie rénale chronique sans dialyse, ces biscuits dorés à la semoule de maïs, croustillants et à l'ancienne, sont pauvres en cholestérol, en sodium, en potassium et en phosphore.",
"24","2 biscuits",
["1 tasse de semoule de maïs jaune finement moulue","1-1/2 tasse de farine blanche tout usage","1-1/2 cuillère à café de levure chimique","1/8 cuillère à café de sel","1 tasse de beurre non salé (2 bâtonnets)","1 tasse de sucre cristallisé","1/2 tasse de substitut d'œuf liquide pauvre en cholestérol","1 cuillère à café d'extrait de vanille"],
["Préchauffez le four à 350° F.","Graissez une plaque de cuisson.","Tamisez ensemble la semoule de maïs, la farine, la levure chimique et le sel dans un bol. Réservez.","Dans un autre bol, crémez le beurre et le sucre jusqu'à ce que le mélange soit léger et mousseux. Incorporez en battant le substitut d'œuf et l'extrait de vanille.","Ajoutez les ingrédients secs au mélange de beurre et battez jusqu'à ce que le tout soit bien mélangé.","Déposez des cuillères à café bien combles de pâte sur la plaque graissée, en rangées espacées d'environ 2 po.","Faites cuire 7 à 8 minutes, jusqu'à ce que les biscuits soient dorés sur les bords. Transférez-les sur une grille pour les laisser refroidir."],
["L'utilisation d'un substitut d'œuf liquide à la place des œufs aide à réduire le phosphore dans cette recette. C'est important dans les recettes qui contiennent de la levure chimique, un ingrédient riche en phosphore nécessaire pour de nombreux produits de boulangerie."],
["1/2 féculent","1 matière grasse","1/2 calorie élevée"]))
o.append(R(2797,"Brie et chutney de canneberges",
"Une diététicienne rénale DaVita partage sa recette de brie et chutney de canneberges pour les personnes qui suivent une alimentation adaptée aux reins. Les personnes atteintes d'une maladie rénale ou de diabète, ou sous dialyse, peuvent savourer le brie et chutney de canneberges proposé sur DaVita.com.",
"10","3/4 once de brie, 2 cuillères à café de chutney et 3 crackers pauvres en sodium",
["12 onces de canneberges fraîches","1/3 tasse d'eau","1/2 tasse de sucre","1/2 tasse de cassonade","1 cuillère à café de moutarde en poudre","1 cuillère à café de clous de girofle","1 cuillère à café de cannelle","1 cuillère à café de muscade","1 cuillère à café de quatre-épices","8 onces de fromage brie","30 crackers pauvres en sodium"],
["Préchauffez le four à 350° F. Lavez et égouttez les canneberges fraîches.","Dans une grande poêle, chauffez l'eau à feu moyen pendant 5 minutes et ajoutez les canneberges fraîches. Chauffez au maximum 5 minutes, juste jusqu'à ce que les canneberges commencent à éclater.","Ajoutez le sucre blanc et la cassonade (ou du Splenda).","Ajoutez les épices et remuez doucement.","Retirez du feu. Laissez refroidir le chutney.","Retirez la meule de brie de son emballage. En laissant une bordure de croûte de 1/2 pouce sur le dessus, découpez un cercle et retirez la croûte du centre pour dévoiler le brie.","Placez le brie sur une plaque de cuisson et faites-le chauffer au four juste jusqu'à ce que le fromage soit mou au toucher et que le dessus soit légèrement fondu.","Sortez le brie du four et déposez-le sur un plat.","Versez le chutney tiède sur le brie et servez avec un assortiment de crackers pauvres en sodium."],
["Les canneberges fraîches sont vendues en sachets de 12 onces.","Il est recommandé d'utiliser des crackers pauvres en sodium pour aider à maintenir un faible apport en sodium.","Remplacez les sucres par 1/2 tasse de Splenda® granulé et 1/4 tasse de mélange Splenda® type cassonade. Ces substitutions réduisent les glucides à 19 grammes par portion, soit 1 choix de glucides.","Le chutney de canneberges peut être préparé et réfrigéré trois jours avant d'être servi.","Le chutney de canneberges est un délicieux accompagnement pour la dinde ou l'agneau, ou peut être tartiné sur un sandwich à la dinde pour une saveur savoureuse."],
["1 viande","1/2 fruit, faible teneur en potassium","1 féculent","1 calorie élevée","1 matière grasse"]))
o.append(R(2798,"Chutney de coriandre",
"Le chutney de coriandre est une préparation rafraîchissante pour les collations ou à tartiner sur vos sandwichs ; il a été mis au point par la mère d'un patient dialysé DaVita et proposé par une diététicienne rénale DaVita.",
"30","1 cuillère à soupe",
["2 tasses de coriandre fraîche","1 piment vert frais","1 oignon rouge moyen","2 gousses d'ail","1 cuillère à soupe de graines de cumin entières","1/2 cuillère à café de sel","2 cuillères à soupe de jus de citron"],
["Lavez la coriandre et le piment vert.","Hachez grossièrement l'oignon, l'ail, la coriandre et le piment.","Broyez le tout dans un mixeur avec le sel, le cumin et le jus de citron.","Servez avec des idli, dans un sandwich aux légumes ou avec d'autres collations."],
["Au lieu de 2 tasses de coriandre, utilisez 2/3 tasse de coriandre et 1/3 tasse de menthe pour une saveur plus douce.","Un bouquet de coriandre représente environ 2 tasses.","Ajustez le piment selon le niveau de piquant désiré.","Réduisez la portion à une cuillère à café si vous l'utilisez avec une collation, ou à 1 cuillère à soupe si vous l'utilisez comme tartinade pour sandwich."],
["aucun"]))
o.append(R(2799,"Riz frit végétarien aux œufs",
"June, de Floride, sait que ses patients dialysés ont envie de riz frit chinois de temps à autre ; elle a donc mis son talent à l'œuvre pour créer une recette de riz frit végétarien aux œufs plus pauvre en sodium, en potassium et en phosphore, adaptée à l'alimentation des personnes dialysées. Le riz basmati associé au tofu extra-ferme, aux œufs, à l'ail, au gingembre et aux légumes offre une saveur et une texture authentiques. Pendant que vous préparez cette recette, rappelez-vous que Confucius disait : « Peu importe la lenteur de votre allure, pourvu que vous ne vous arrêtiez pas. »",
"6","1 tasse",
["2 gousses d'ail","1 cuillère à soupe de gingembre frais","1 tasse de carottes fraîches","1 tasse d'oignon jaune","1 tasse de tofu extra-ferme","1/2 tasse de coriandre fraîche","1/2 tasse d'oignons verts","6 gros œufs","1 cuillère à soupe de sauce soja à teneur réduite en sodium","3 cuillères à soupe d'huile de canola","1/2 tasse de petits pois","1/4 cuillère à café de moutarde en poudre","4 tasses de riz cuit"],
["Hachez finement l'ail et le gingembre. Coupez les carottes en rondelles. Coupez l'oignon jaune et le tofu en dés. Hachez la coriandre et les oignons verts.","Battez les œufs puis faites-les cuire dans une poêle comme une omelette. Coupez les œufs cuits en morceaux et réservez.","Chauffez l'huile dans une poêle à feu modéré. Ajoutez en remuant l'ail, le gingembre, les carottes, l'oignon jaune, le tofu, les petits pois et la moutarde en poudre.","Lorsque les carottes sont tendres, ajoutez le riz, les œufs en morceaux et la sauce soja. Mélangez et éteignez le feu.","Incorporez la coriandre et les oignons verts."],
["Le riz basmati a un meilleur profil glycémique que les autres types de riz blanc. Il contient aussi moins de phosphore que le riz brun.","Pour réduire le cholestérol, vous pouvez utiliser 1-1/2 tasse de substitut d'œuf pauvre en cholestérol à la place des 6 œufs."],
["1-1/2 viande","2 féculent","1 légume, teneur moyenne en potassium","1 matière grasse"]))
o.append(R(2801,"Tibs de bœuf",
"Le tibs de bœuf, un plat éthiopien populaire à base de bœuf épicé, est juteux et délicieux. Dans sa forme traditionnelle, il n'est pas très adapté aux reins, mais Hanna, diététicienne rénale DaVita du Maryland, l'a adapté afin que les personnes dialysées puissent le savourer.",
"2","environ 1-1/2 tasse",
["1 petit oignon","1/2 tomate moyenne","1/2 poivron vert moyen","8 onces de bœuf maigre à ragoût","2 cuillères à soupe d'huile de canola","1/4 cuillère à café de sel","1/8 cuillère à café de poivre noir"],
["Émincez finement l'oignon. Hachez la tomate et le poivron. Coupez le bœuf en petits cubes.","Faites sauter l'oignon dans l'huile dans une poêle jusqu'à ce qu'il soit légèrement doré. Ajoutez le bœuf et les tomates.","Lorsque la viande est partiellement cuite, ajoutez le poivron, le sel et le poivre.","Poursuivez la cuisson jusqu'à ce que la viande soit tendre."],
["Le tibs est un plat éthiopien courant qui peut être servi avec du pain pita, une demi-injera ou 1 tasse de riz cuit.","Vous pouvez préparer des variantes de tibs de bœuf en ajoutant différents ingrédients de votre choix.","Ajoutez 1 piment jalapeño si vous préférez un goût plus épicé.","En n'utilisant qu'une petite quantité de tomate, le tibs de bœuf devient un plat approprié pour les patients dialysés.","Ajustez la portion pour un régime plus pauvre en protéines en cas de maladie rénale chronique sans dialyse."],
["3 viande","1 légume, teneur moyenne en potassium","1 matière grasse"]))
o.append(R(2802,"Tartinade crémeuse au concombre",
"Une diététicienne DaVita de l'Alabama partage une entrée légère et rafraîchissante, parfaite pour lutter contre la chaleur. La tartinade crémeuse au concombre vous mettra l'eau à la bouche. Elle est adaptée aux reins, facile à préparer et convient aussi bien à la maison qu'à un pique-nique au parc ou à la plage.",
"8","1/4 tasse",
["8 onces de fromage à la crème","1 concombre moyen","1 cuillère à café d'oignon","1 cuillère à soupe de mayonnaise"],
["Sortez le fromage à la crème pour qu'il ramollisse.","Pelez le concombre, épépinez-le et hachez-le très finement, puis réservez. Hachez l'oignon.","Mélangez le fromage à la crème, l'oignon et la mayonnaise dans un petit bol jusqu'à obtenir une texture lisse.","Incorporez délicatement le concombre au mélange jusqu'à ce qu'il soit réparti uniformément."],
["Le fromage à la crème allégé ou sans matières grasses fonctionne très bien aussi.","La tartinade crémeuse au concombre donne de délicieux petits sandwichs. Retirez la croûte du pain et coupez les sandwichs en triangles pour de jolies bouchées apéritives.","Cette recette est délicieuse sur des crackers salins à faible teneur en sel."],
["1/2 lait","1 matière grasse"]))
o.append(R(2803,"Poulet au pesto sur petits pains ciabatta",
"Le poulet au pesto sur petits pains ciabatta n'est pas votre sandwich habituel à la salade de poulet. Le pesto au basilic et les petits pains ciabatta moelleux relèvent sans aucun doute la saveur de ce sandwich adapté aux reins.",
"2","1 sandwich",
["1 tasse de blanc de poulet cuit, effiloché","2 cuillères à soupe de yogourt grec","2 cuillères à soupe de pesto","1/8 cuillère à café de poivre noir","2 petits pains ciabatta","1 tasse de laitue râpée"],
["Dans un bol moyen, mélangez le poulet effiloché, le pesto, le yogourt grec et le poivre noir.","Coupez les petits pains ciabatta en deux et faites-les griller.","Divisez le mélange de poulet au pesto en deux et préparez les sandwichs avec les petits pains. Ajoutez de la laitue râpée selon votre goût."],
["Utilisez de la roquette hachée à la place de la laitue si vous le souhaitez. Les nutriments sont similaires.","Pour un sandwich plus pauvre en protéines, réduisez de moitié les ingrédients du mélange de poulet au pesto. La teneur en protéines est d'environ 21 grammes par sandwich.","Pour réduire les glucides, servez le mélange sur une demi mini-baguette au lieu du petit pain ciabatta. Les glucides passent à 26 grammes."],
["3 viande","2-1/2 féculent"]))
o.append(R(2806,"Salade croquante au pain de maïs",
"La salade croquante au pain de maïs a été créée par Sara, diététicienne rénale DaVita en Californie. Il lui restait du pain de maïs de sa recette de pain de maïs à la sudiste et elle a découvert qu'il apportait énormément de saveur à une salade. En tant que diététicienne rénale, Sara sait rendre les plats adaptés aux reins pour les personnes dialysées et, comme elle aime cuisiner, elle sait aussi les rendre délicieux.",
"6","1-1/3 tasse",
["6 tasses de laitue iceberg","1/2 tasse de poivron","1/2 tasse de radis","1/2 tasse de concombre","1/2 tasse de coriandre fraîche","2 tasses de pain de maïs à la sudiste","1/2 tasse de crème sure","2 cuillères à soupe de mayonnaise","3/4 cuillère à café de préparation sèche en poudre pour vinaigrette ranch"],
["Râpez la laitue, hachez le poivron et la coriandre, coupez les radis en rondelles, puis pelez et coupez les concombres en dés.","Mélangez le tout dans un grand saladier.","Incorporez le pain de maïs émietté.","Dans un autre bol, mélangez la crème sure, la mayonnaise et la préparation pour vinaigrette ranch.","Versez le mélange de crème sure sur la salade et mélangez bien.","Réfrigérez avant de servir."],
["Une excellente façon d'utiliser les restes de pain de maïs.","Essayez la recette de pain de maïs à la sudiste de DaVita.com : elle est pauvre en sodium et en phosphore, mais pleine de saveur."],
["1-1/2 féculent","1 légume, teneur moyenne en potassium","2 matière grasse"]))
o.append(R(2808,"Café Coco-Loco pour une tablée",
"Ajoutez une touche de saveur supplémentaire à votre café du petit-déjeuner ou du brunch avec le café Coco-Loco pour une tablée d'Elyse.",
"7","8 onces",
["6 tasses de café fort préparé","1 tasse de lait de coco","2 cuillères à soupe d'extrait de vanille","1/4 tasse de stévia brute ou d'édulcorant de votre choix","Une pincée de cannelle pour saupoudrer"],
["Préparez le café et transférez-le dans une grande carafe.","Mélangez le lait de coco, la vanille et la stévia dans une petite casserole à feu moyen. Portez à léger frémissement en remuant au fouet pendant environ 5 minutes.","Mélangez le mélange de lait avec le café préparé.","Versez 8 onces dans 7 tasses. Saupoudrez de cannelle et savourez !"],
["Servez en boisson de café froide en réfrigérant le café préparé et le mélange de lait pendant une heure avant de servir.","Remplacez la stévia par du sucre ou l'édulcorant de votre choix.","Certains substituts de lait sont riches en calcium. Elyse utilise du lait de coco non sucré So Delicious, qui ne contient que 130 mg de calcium, 40 mg de potassium et 46 mg de phosphore par tasse."],
["aucun"]))
o.append(R(2809,"Courgettes sautées",
"Les courgettes sautées sont une savoureuse façon d'intégrer des légumes à votre alimentation adaptée aux reins. Savourez cette recette proposée par Usha, diététicienne DaVita.",
"4","1/2 tasse",
["1 cuillère à soupe de beurre","1 cuillère à soupe d'huile d'olive","1 cuillère à café de graines de cumin","2 tasses de courgettes","1/2 tasse d'oignon rouge","1 cuillère à café de poivre noir","1 cuillère à soupe de jus de citron","1/4 tasse de coriandre fraîche"],
["Pelez et coupez en tranches les courgettes et l'oignon. Hachez la coriandre.","Chauffez le beurre et l'huile d'olive dans une poêle antiadhésive à feu moyen.","Faites revenir les graines de cumin jusqu'à ce qu'elles dorent.","Ajoutez les courgettes et l'oignon et saupoudrez de poivre noir. Remuez plusieurs fois pour mélanger.","Couvrez et faites cuire environ 5 minutes jusqu'à ce que les légumes soient moyennement tendres, en remuant de temps en temps.","Ajoutez le jus de citron et la coriandre hachée. Mélangez, laissez cuire encore une minute et servez."],
["Les feuilles de coriandre sont aussi connues sous les noms de coriandre, dhania, persil chinois et persil mexicain."],
["1 légume, teneur moyenne en potassium","1 matière grasse"]))
o.append(R(2813,"Vinaigrette italienne",
"La vinaigrette italienne est un classique pour assaisonner les salades dans toutes les cuisines, et cette recette se trouve être adaptée aux reins.",
"16","2 cuillères à soupe",
["1 cuillère à soupe de persil séché","1/4 cuillère à café d'origan moulu","1/2 cuillère à café de thym moulu","1/4 cuillère à café de marjolaine moulue","1/2 cuillère à café de graines de céleri moulues","1/4 cuillère à café d'ail en poudre","1 cuillère à café de sucre cristallisé","1/8 cuillère à café de sel","1 pincée de poivre noir","1/2 tasse de vinaigre de vin rouge","1/2 tasse d'huile d'olive extra vierge"],
["Mélangez les assaisonnements.","Ajoutez-les au vinaigre et à l'huile.","Agitez bien pour mélanger."],
["Les vinaigrettes maison se conservent bien au réfrigérateur pendant plusieurs semaines.","Pour varier, essayez différentes huiles, y compris des huiles aromatisées ou épicées."],
["1-1/2 matière grasse"]))
o.append(R(2815,"Pancake au four super simple",
"Le pancake au four super simple est une délicieuse recette proposée par Peggy, patiente DaVita du Missouri. Cette pâte à pancake adaptée aux reins n'est pas cuite de la manière traditionnelle, mais au four, ce qui donne une nouvelle façon de cuisiner un pancake.",
"4","1 part ou 1/4 de la recette",
["2 gros œufs","1/2 tasse de lait","1/2 tasse de farine blanche tout usage","1/4 cuillère à café de sel","1/8 cuillère à café de muscade","1 cuillère à soupe d'huile végétale"],
["Préchauffez le four à 450° F.","Battez les œufs et le lait dans un bol moyen avec un fouet ou un batteur électrique.","Incorporez en battant la farine, le sel et la muscade jusqu'à ce que le tout soit mélangé (de petits grumeaux de farine dans la pâte ne posent pas de problème).","Versez l'huile dans une poêle allant au four de 9 po ou un moule à tarte et placez-la dans le four préchauffé pendant 5 minutes pour chauffer l'huile.","Versez délicatement la pâte dans la poêle et faites cuire à découvert 18 à 20 minutes. (Évitez d'ouvrir la porte du four avant que le pancake soit gonflé et croustillant sur les bords. Le centre sera doré une fois cuit.)","Coupez en 4 parts et servez avec du sirop de pancake ou de la tartinade de fruits."],
["Remplacez le lait par un substitut non laitier, tel que du lait de riz non enrichi ou une crème non laitière. Le phosphore et le potassium seront légèrement réduits.","Pour plus de protéines, ajoutez un blanc d'œuf supplémentaire."],
["1/2 viande","2 féculent","1 matière grasse"]))
save(o,2)
